for_loop.code:
// Standard C loop
for (int i = 0; i < 5; i++) {
    NSLog(@"%d", i);
}

// Fast enumeration over collections
NSArray *arr = @[@"a", @"b", @"c"];
for (NSString *item in arr) {
    NSLog(@"%@", item);
}

while_loop.code:
int x = 0;
while (x < 5) {
    x++;
}

int y = 0;
do {
    y++;
} while (y < 5);

functions.code:
// C-style function
int add(int a, int b) { return a + b; }

// Objective-C Method declaration
- (int)addNumber:(int)a toNumber:(int)b {
    return a + b;
}

// Calling the method
int res = [self addNumber:3 toNumber:4];

